package com.wipro.hibernate;import org.hibernate.*;import java.math.*;public class Main{public static void main(String[]a){try(Session s=HibernateUtil.getSessionFactory().openSession()){Transaction t=s.beginTransaction();Flower f=new Flower();f.setFlowerId("F001");f.setFlowerName("Rose");f.setColor("Red");f.setPrice(new BigDecimal("10"));s.persist(f);t.commit();System.out.println("Flower record inserted successfully.");}HibernateUtil.getSessionFactory().close();}}